from pathlib import Path
import base64, zlib

OUT = Path('main/boards/xingzhi-cube-1.83tft-wifi/mochi_action_food_assets_15q.h')

# 15Q clean food sprites reconstructed from the approved full artwork sheet.
# Every frame is a complete standalone 68x54 RGBA canvas with identical anchor.
# Visible pixels are hard-alpha and RGB565-snapped; no runtime scaling or cropping.
DATA = {
    'fish0': '',
    'fish1': '',
    'fish2': '',
    'meal0': '',
    'meal1': '',
    'meal2': '',
    'dessert0': '',
    'dessert1': '',
    'dessert2': '',
}

def emit(lines, name, blob):
    raw = zlib.decompress(base64.b64decode(blob))
    assert len(raw) == 68 * 54 * 4
    arr = name + '_map'
    lines.append(f'alignas(4) static const uint8_t {arr}[] = {{')
    for i in range(0, len(raw), 20):
        lines.append('    ' + ', '.join(f'0x{x:02X}' for x in raw[i:i+20]) + ',')
    lines += [
        '};',
        f'static const lv_image_dsc_t {name} = {{',
        '    {LV_IMAGE_HEADER_MAGIC, LV_COLOR_FORMAT_ARGB8888, 0, 68, 54, 272, 0},',
        f'    sizeof({arr}), {arr}, nullptr, nullptr',
        '};',
        ''
    ]

lines = [
    '#pragma once', '', '#include <lvgl.h>', '#include <cstddef>', '',
    '// Mochi 15Q CLEAN FOOD: approved art reconstructed from full uncropped source.',
    '// All 9 frames: exactly 68x54, same bottom-center anchor, 2px+ safe padding.',
    '// RGB565-snapped palette, no dithering, alpha is binary 0/255.',
    ''
]
for key in ('fish0','fish1','fish2','meal0','meal1','meal2','dessert0','dessert1','dessert2'):
    emit(lines, 'mochi_action_15q_' + key, DATA[key])

lines += [
    'static const lv_image_dsc_t* const kMochiActionFoodStages15Q[3][3] = {',
    '    {&mochi_action_15q_fish0, &mochi_action_15q_fish1, &mochi_action_15q_fish2},',
    '    {&mochi_action_15q_meal0, &mochi_action_15q_meal1, &mochi_action_15q_meal2},',
    '    {&mochi_action_15q_dessert0, &mochi_action_15q_dessert1, &mochi_action_15q_dessert2},',
    '};', ''
]
OUT.write_text('\n'.join(lines), encoding='utf-8')
print('Generated Mochi 15Q clean food sprites', OUT, OUT.stat().st_size)